'use client';

import { cn } from "@/lib/utils";
import { motion, Variants } from "motion/react";

type Props = {
  children: React.ReactNode;
  fg?:string;
  bg?:string;
  isOrchestrated?: boolean;
}

const pillVariants: Variants = {
  initial: {
    opacity: 0,
  },
  animate: {
    opacity: 0,
  },
  whileHover: {
    opacity: 1,
  },
  whileInView: {
    opacity: 1,
  },
  exit: {
    opacity: 0,
  },
}

export default function Pill({
  children,
  fg = 'text-foreground',
  bg = 'bg-background-lighten',
  isOrchestrated = false
}: Props) {
  return (
    <motion.div
      className={cn(
        "rounded-full px-4 py-2 text-sm font-semibold",
        fg,
        bg
      )}
      variants={pillVariants}
      initial={!isOrchestrated ? 'initial' : undefined}
      animate={!isOrchestrated ? 'animate' : undefined}
      whileHover={!isOrchestrated ? 'whileHover' : undefined}
      whileInView={!isOrchestrated ? 'whileInView' : undefined}
      exit={!isOrchestrated ? 'exit' : undefined}
    >
      {children}
    </motion.div>
  );
}